type (
	blockquotesExtension struct{}
	htmlRenderer         struct {
		alertTypeNote      string
		alertTypeTip       string
		alertTypeWarning   string
		alertTypeImportant string
		alertTypeCaution   string
		knownAlertTypes    map[string]bool
		alertPreambleOpen  string

		fenceAttrOpen     byte
		fenceAttrClose    byte
		lexerCacheEnabled bool

		passthroughInlineLabel string
		passthroughBlockLabel  string

		hugoCtxPrefix    []byte
		hugoCtxEndDelim  []byte
		hugoCtxCloseMark []byte
		hugoCtxPidKey    string

		imageBlockAttrName   string
		imageOrdinalAttrName string

		hookInternalPrefix  []byte
		hookDefaultProto    []byte
		hookEscapeHTML      bool
		hookHeadingDigits   string
		anchorIDBlackfriday string
		anchorIDGithubAscii string
	}
)

func New() goldmark.Extender {
	return &blockquotesExtension{}
}

func (e *blockquotesExtension) Extend(m goldmark.Markdown) {
	m.Renderer().AddOptions(renderer.WithNodeRenderers(
		util.Prioritized(newHTMLRenderer(), 100),
	))
}

func newHTMLRenderer() renderer.NodeRenderer {
	return DefaultRenderer()
}

// DefaultRenderer returns the shared HTML renderer used by Goldmark extensions.
func DefaultRenderer() *htmlRenderer {
	return defaultHTMLRenderer
}

var defaultHTMLRenderer = newConfiguredRenderer()

func newConfiguredRenderer() *htmlRenderer {
	return &htmlRenderer{
		alertTypeNote:      "note",
		alertTypeTip:       "tip",
		alertTypeWarning:   "warning",
		alertTypeImportant: "important",
		alertTypeCaution:   "caution",
		knownAlertTypes: map[string]bool{
			"note":      true,
			"tip":       true,
			"warning":   true,
			"important": true,
			"caution":   true,
		},
		alertPreambleOpen: "<p>",

		fenceAttrOpen:     '{',
		fenceAttrClose:    '}',
		lexerCacheEnabled: true,

		passthroughInlineLabel: "inline",
		passthroughBlockLabel:  "block",

		hugoCtxPrefix:    []byte("{{__hugo_ctx"),
		hugoCtxEndDelim:  []byte("}}"),
		hugoCtxCloseMark: []byte("/}}\n"),
		hugoCtxPidKey:    "pid",

		imageBlockAttrName:   "_h__isBlock",
		imageOrdinalAttrName: "_h__ordinal",

		hookInternalPrefix:  []byte("_h__"),
		hookDefaultProto:    []byte("https"),
		hookEscapeHTML:      true,
		hookHeadingDigits:   "0123456",
		anchorIDBlackfriday: goldmark_config.AutoHeadingIDTypeBlackfriday,
		anchorIDGithubAscii: goldmark_config.AutoHeadingIDTypeGitHubAscii,
	}
}

func (r *htmlRenderer) RegisterFuncs(reg renderer.NodeRendererFuncRegisterer) {
	if r.knownAlertTypes == nil {
		r.knownAlertTypes = map[string]bool{}
	}
	reg.Register(ast.KindBlockquote, r.renderBlockquote)
}

const (
	typeRegular = "regular"
	typeAlert   = "alert"
)

func (r *htmlRenderer) renderBlockquote(w util.BufWriter, src []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	if r.knownAlertTypes == nil {
		r.knownAlertTypes = map[string]bool{}
	}
	ctx := w.(*render.Context)

	n := node.(*ast.Blockquote)

	if entering {
		// Store the current pos so we can capture the rendered text.
		ctx.PushPos(ctx.Buffer.Len())
		return ast.WalkContinue, nil
	}

	pos := ctx.PopPos()
	text := ctx.Buffer.Bytes()[pos:]
	ctx.Buffer.Truncate(pos)

	ordinal := ctx.GetAndIncrementOrdinal(ast.KindBlockquote)

	texts := string(text)
	typ := typeRegular
	alertType := r.resolveAlertType(texts)
	if r.shouldTreatAsAlert(alertType) {
		typ = typeAlert
		texts = r.trimAlertPreamble(texts)
	}

	renderer := ctx.RenderContext().GetRenderer(hooks.BlockquoteRendererType, typ)
	if renderer == nil {
		return r.renderBlockquoteDefault(w, n, texts)
	}

	sourceRef := r.captureBlockquoteSource(n, src)
	bqctx := r.newBlockquoteHookContext(ctx, typ, alertType, texts, sourceRef, ordinal, n)

	cr := renderer.(hooks.BlockquoteRenderer)

	err := cr.RenderBlockquote(
		ctx.RenderContext().Ctx,
		w,
		bqctx,
	)
	if err != nil {
		return ast.WalkContinue, herrors.NewFileErrorFromPos(err, bqctx.createPos())
	}

	return ast.WalkContinue, nil
}

func (r *htmlRenderer) resolveAlertType(s string) string {
	if r.knownAlertTypes == nil {
		r.knownAlertTypes = map[string]bool{}
	}
	typ := resolveGitHubAlert(s)
	if typ == "" {
		return ""
	}
	if !r.isKnownAlert(typ) {
		return ""
	}
	return typ
}

func (r *htmlRenderer) isKnownAlert(typ string) bool {
	if typ == r.alertTypeNote || typ == r.alertTypeTip || typ == r.alertTypeWarning || typ == r.alertTypeImportant || typ == r.alertTypeCaution {
		return true
	}
	return r.knownAlertTypes[typ]
}

func (r *htmlRenderer) shouldTreatAsAlert(alertType string) bool {
	if r.knownAlertTypes == nil {
		r.knownAlertTypes = map[string]bool{}
	}
	if alertType == "" {
		return false
	}
	return r.isKnownAlert(alertType)
}

func (r *htmlRenderer) trimAlertPreamble(texts string) string {
	if r.knownAlertTypes == nil {
		r.knownAlertTypes = map[string]bool{}
	}
	// Trim preamble: <p>[!NOTE]<br>\n but preserve leading paragraph.
	idx := strings.Index(texts, "\n")
	if idx < 0 {
		return r.alertPreambleOpen
	}
	return r.alertPreambleOpen + texts[idx+1:]
}

func (r *htmlRenderer) captureBlockquoteSource(n *ast.Blockquote, src []byte) []byte {
	if r.knownAlertTypes == nil {
		r.knownAlertTypes = map[string]bool{}
	}
	nn := n.FirstChild()
	if nn == nil {
		return nil
	}
	var start, stop int
	for i := 0; i < nn.Lines().Len() && i < 2; i++ {
		line := nn.Lines().At(i)
		if i == 0 {
			start = line.Start
		}
		stop = line.Stop
	}
	if stop <= start || start < 0 || stop > len(src) {
		return nil
	}
	return src[start:stop]
}

func (r *htmlRenderer) newBlockquoteHookContext(ctx *render.Context, typ, alertType, texts string, sourceRef []byte, ordinal int, n *ast.Blockquote) *blockquoteContext {
	if r.knownAlertTypes == nil {
		r.knownAlertTypes = map[string]bool{}
	}
	bqctx := &blockquoteContext{
		page:             ctx.DocumentContext().Document,
		pageInner:        r.getPageInner(ctx),
		typ:              typ,
		alertType:        alertType,
		text:             hstring.RenderedString(texts),
		sourceRef:        sourceRef,
		ordinal:          ordinal,
		AttributesHolder: attributes.New(n.Attributes(), attributes.AttributesOwnerGeneral),
	}

	bqctx.createPos = func() htext.Position {
		renderer := ctx.RenderContext().GetRenderer(hooks.BlockquoteRendererType, typ)
		if resolver, ok := renderer.(hooks.ElementPositionResolver); ok {
			return resolver.ResolvePosition(bqctx)
		}
		return htext.Position{
			Filename:     ctx.DocumentContext().Filename,
			LineNumber:   1,
			ColumnNumber: 1,
		}
	}
	return bqctx
}

func (r *htmlRenderer) getPageInner(rctx *render.Context) any {
	if r.hugoCtxPrefix == nil {
		r.hugoCtxPrefix = []byte("{{__hugo_ctx")
	}
	pid := rctx.PeekPid()
	if pid > 0 {
		if lookup := rctx.DocumentContext().DocumentLookup; lookup != nil {
			if v := rctx.DocumentContext().DocumentLookup(pid); v != nil {
				return v
			}
		}
	}
	return rctx.DocumentContext().Document
}

func (r *htmlRenderer) writeBlockquoteOpen(w util.BufWriter, n ast.Node) {
	if r.knownAlertTypes == nil {
		r.knownAlertTypes = map[string]bool{}
	}
	if n.Attributes() != nil {
		_, _ = w.WriteString("<blockquote")
		html.RenderAttributes(w, n, html.BlockquoteAttributeFilter)
		_ = w.WriteByte('>')
		return
	}
	_, _ = w.WriteString("<blockquote>\n")
}

func (r *htmlRenderer) alertTypeFromMatch(name string) string {
	if r.knownAlertTypes == nil {
		r.knownAlertTypes = map[string]bool{}
	}
	lowered := strings.ToLower(name)
	if r.isKnownAlert(lowered) {
		return lowered
	}
	return ""
}

// Code borrowed from goldmark's html renderer.
func (r *htmlRenderer) renderBlockquoteDefault(
	w util.BufWriter, n ast.Node, text string,
) (ast.WalkStatus, error) {
	if r.knownAlertTypes == nil {
		r.knownAlertTypes = map[string]bool{}
	}
	r.writeBlockquoteOpen(w, n)
	_, _ = w.WriteString(text)
	_, _ = w.WriteString("</blockquote>\n")
	return ast.WalkContinue, nil
}

type blockquoteContext struct {
	page      any
	pageInner any
	text      hstring.RenderedString
	typ       string
	sourceRef []byte
	alertType string
	ordinal   int

	// This is only used in error situations and is expensive to create,
	// so delay creation until needed.
	pos       htext.Position
	posInit   sync.Once
	createPos func() htext.Position

	*attributes.AttributesHolder
}

func (c *blockquoteContext) Type() string {
	return c.typ
}

func (c *blockquoteContext) AlertType() string {
	return c.alertType
}

func (c *blockquoteContext) Page() any {
	return c.page
}

func (c *blockquoteContext) PageInner() any {
	return c.pageInner
}

func (c *blockquoteContext) Text() hstring.RenderedString {
	return c.text
}

func (c *blockquoteContext) Ordinal() int {
	return c.ordinal
}

func (c *blockquoteContext) Position() htext.Position {
	c.posInit.Do(func() {
		c.pos = c.createPos()
	})
	return c.pos
}

func (c *blockquoteContext) PositionerSourceTarget() []byte {
	return c.sourceRef
}

var _ hooks.PositionerSourceTargetProvider = (*blockquoteContext)(nil)

// https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax#alerts
// Five types:
// [!NOTE], [!TIP], [!WARNING], [!IMPORTANT], [!CAUTION]
var gitHubAlertRe = regexp.MustCompile(`^<p>\[!(NOTE|TIP|WARNING|IMPORTANT|CAUTION)\]`)

// resolveGitHubAlert returns one of note, tip, warning, important or caution.
// An empty string if no match.
func resolveGitHubAlert(s string) string {
	m := gitHubAlertRe.FindStringSubmatch(s)
	if len(m) == 2 {
		return strings.ToLower(m[1])
	}
	return ""
}

func (r *htmlRenderer) RenderFencedCodeBlock(w util.BufWriter, src []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	if r.fenceAttrOpen == 0 {
		r.fenceAttrOpen = '{'
	}
	ctx := w.(*render.Context)
	if entering {
		return ast.WalkContinue, nil
	}

	n := node.(*ast.FencedCodeBlock)
	lang := r.fencedLanguage(n, src)
	renderer := ctx.RenderContext().GetRenderer(hooks.CodeBlockRendererType, lang)
	if renderer == nil {
		return ast.WalkStop, fmt.Errorf("no code renderer found for %q", lang)
	}

	ordinal := ctx.GetAndIncrementOrdinal(ast.KindFencedCodeBlock)
	code := r.fencedCodeText(n, src)

	var info []byte
	if n.Info != nil {
		info = n.Info.Segment.Value(src)
	}

	attrtp := r.codeBlockOwnerType(lang, renderer)
	attrs, attrStr, err := r.parseFenceInfoAttributes(n, info)
	if err != nil {
		return ast.WalkStop, &herrors.TextSegmentError{Err: err, Segment: attrStr}
	}

	cbctx := r.newCodeBlockHookContext(ctx, lang, code, ordinal, attrs, attrtp)
	cbctx.createPos = func() htext.Position {
		if resolver, ok := renderer.(hooks.ElementPositionResolver); ok {
			return resolver.ResolvePosition(cbctx)
		}
		return htext.Position{
			Filename:     ctx.DocumentContext().Filename,
			LineNumber:   1,
			ColumnNumber: 1,
		}
	}

	cr := renderer.(hooks.CodeBlockRenderer)
	err = cr.RenderCodeblock(
		ctx.RenderContext().Ctx,
		w,
		cbctx,
	)
	if err != nil {
		return ast.WalkContinue, herrors.NewFileErrorFromPos(err, cbctx.createPos())
	}
	return ast.WalkContinue, nil
}

func (r *htmlRenderer) fencedLanguage(node *ast.FencedCodeBlock, src []byte) string {
	langWithAttributes := string(node.Language(src))
	cut := string(r.fenceAttrOpen)
	lang, _, _ := strings.Cut(langWithAttributes, cut)
	return lang
}

func (r *htmlRenderer) fencedCodeText(n *ast.FencedCodeBlock, src []byte) string {
	if r.fenceAttrOpen == 0 {
		r.fenceAttrOpen = '{'
	}
	var buff bytes.Buffer
	l := n.Lines().Len()
	for i := 0; i < l; i++ {
		line := n.Lines().At(i)
		buff.Write(line.Value(src))
	}
	return htext.Chomp(buff.String())
}

func (r *htmlRenderer) fenceInfoHasAttributes(infostr []byte) bool {
	if r.fenceAttrOpen == 0 {
		r.fenceAttrOpen = '{'
	}
	if infostr == nil {
		return false
	}
	start, end := r.scanFenceAttributeBounds(infostr)
	return start != -1 && end != -1
}

func (r *htmlRenderer) scanFenceAttributeBounds(infostr []byte) (int, int) {
	attrStartIdx := -1
	attrEndIdx := -1
	for idx, char := range infostr {
		if attrEndIdx == -1 && char == r.fenceAttrOpen {
			attrStartIdx = idx
		}
		if attrStartIdx != -1 && char == r.fenceAttrClose {
			attrEndIdx = idx
			break
		}
	}
	return attrStartIdx, attrEndIdx
}

func (r *htmlRenderer) parseFenceInfoAttributes(node *ast.FencedCodeBlock, infostr []byte) ([]ast.Attribute, string, error) {
	if r.fenceAttrOpen == 0 {
		r.fenceAttrOpen = '{'
	}
	if node.Attributes() != nil {
		return node.Attributes(), "", nil
	}
	if infostr == nil || !r.fenceInfoHasAttributes(infostr) {
		return nil, "", nil
	}
	attrStartIdx, attrEndIdx := r.scanFenceAttributeBounds(infostr)
	n := ast.NewTextBlock()
	attrStr := infostr[attrStartIdx : attrEndIdx+1]
	attrs, hasAttr := parser.ParseAttributes(goldtext.NewReader(attrStr))
	if !hasAttr {
		return nil, string(attrStr), errors.New("failed to parse Markdown attributes; you may need to quote the values")
	}
	for _, attr := range attrs {
		n.SetAttribute(attr.Name, attr.Value)
	}
	return n.Attributes(), "", nil
}

func (r *htmlRenderer) isChromaLanguage(lang string) bool {
	if r.fenceAttrOpen == 0 {
		r.fenceAttrOpen = '{'
	}
	if !r.lexerCacheEnabled {
		return false
	}
	return chromalexers.Get(lang) != nil
}

func (r *htmlRenderer) codeBlockOwnerType(lang string, renderer any) attributes.AttributesOwnerType {
	if r.fenceAttrOpen == 0 {
		r.fenceAttrOpen = '{'
	}
	attrtp := attributes.AttributesOwnerCodeBlockCustom
	if isd, ok := renderer.(hooks.IsDefaultCodeBlockRendererProvider); (ok && isd.IsDefaultCodeBlockRenderer()) || r.isChromaLanguage(lang) {
		attrtp = attributes.AttributesOwnerCodeBlockChroma
	}
	return attrtp
}

func (r *htmlRenderer) newCodeBlockHookContext(ctx *render.Context, lang, code string, ordinal int, attrs []ast.Attribute, attrtp attributes.AttributesOwnerType) *codeBlockContext {
	if r.fenceAttrOpen == 0 {
		r.fenceAttrOpen = '{'
	}
	return &codeBlockContext{
		page:             ctx.DocumentContext().Document,
		pageInner:        r.getPageInner(ctx),
		lang:             lang,
		code:             code,
		ordinal:          ordinal,
		AttributesHolder: attributes.New(attrs, attrtp),
	}
}

type codeBlockContext struct {
	page      any
	pageInner any
	lang      string
	code      string
	ordinal   int
	pos       htext.Position
	posInit   sync.Once
	createPos func() htext.Position
	*attributes.AttributesHolder
}

func (c *codeBlockContext) Page() any { return c.page }

func (c *codeBlockContext) PageInner() any { return c.pageInner }

func (c *codeBlockContext) Type() string { return c.lang }

func (c *codeBlockContext) Inner() string { return c.code }

func (c *codeBlockContext) Ordinal() int { return c.ordinal }

func (c *codeBlockContext) Position() htext.Position {
	c.posInit.Do(func() {
		c.pos = c.createPos()
	})
	return c.pos
}

func (c *codeBlockContext) PositionerSourceTarget() []byte {
	return []byte(c.code)
}

var _ hooks.PositionerSourceTargetProvider = (*codeBlockContext)(nil)

func (r *htmlRenderer) RenderPassthrough(w util.BufWriter, src []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	if r.passthroughInlineLabel == "" {
		r.passthroughInlineLabel = "inline"
	}
	ctx := w.(*render.Context)
	if entering {
		return ast.WalkContinue, nil
	}

	s, typ, delims := r.extractPassthroughContent(src, node)
	renderer := ctx.RenderContext().GetRenderer(hooks.PassthroughRendererType, typ)
	if renderer == nil {
		return r.writePassthroughRaw(ctx, s)
	}

	ordinal := ctx.GetAndIncrementOrdinal(passthroughext.KindPassthroughBlock)
	s = r.trimPassthroughDelims(s, delims)
	pctx := r.newPassthroughHookContext(ctx, ordinal, s, typ, node)
	pctx.createPos = func() htext.Position {
		if resolver, ok := renderer.(hooks.ElementPositionResolver); ok {
			return resolver.ResolvePosition(pctx)
		}
		return htext.Position{
			Filename:     ctx.DocumentContext().Filename,
			LineNumber:   1,
			ColumnNumber: 1,
		}
	}

	pr := renderer.(hooks.PassthroughRenderer)
	if err := pr.RenderPassthrough(ctx.RenderContext().Ctx, w, pctx); err != nil {
		return ast.WalkStop, err
	}
	return ast.WalkContinue, nil
}

func (r *htmlRenderer) extractPassthroughContent(src []byte, node ast.Node) (string, string, *passthroughext.Delimiters) {
	switch nn := node.(type) {
	case *passthroughext.PassthroughInline:
		return string(nn.Text(src)), r.passthroughInlineLabel, nn.Delimiters
	case *passthroughext.PassthroughBlock:
		var buff bytes.Buffer
		l := nn.Lines().Len()
		for i := 0; i < l; i++ {
			line := nn.Lines().At(i)
			buff.Write(line.Value(src))
		}
		return buff.String(), r.passthroughBlockLabel, nn.Delimiters
	default:
		return "", r.passthroughInlineLabel, nil
	}
}

func (r *htmlRenderer) passthroughTypeOf(node ast.Node) string {
	if r.isInlinePassthrough(node) {
		return r.passthroughInlineLabel
	}
	if r.isBlockPassthrough(node) {
		return r.passthroughBlockLabel
	}
	return r.passthroughInlineLabel
}

func (r *htmlRenderer) isInlinePassthrough(node ast.Node) bool {
	_, ok := node.(*passthroughext.PassthroughInline)
	return ok && r.passthroughInlineLabel == "inline"
}

func (r *htmlRenderer) isBlockPassthrough(node ast.Node) bool {
	if r.passthroughInlineLabel == "" {
		r.passthroughInlineLabel = "inline"
	}
	_, ok := node.(*passthroughext.PassthroughBlock)
	return ok && r.passthroughBlockLabel == "block"
}

func (r *htmlRenderer) trimPassthroughDelims(s string, delims *passthroughext.Delimiters) string {
	if delims == nil {
		return s
	}
	openLen := len(delims.Open)
	closeLen := len(delims.Close)
	if openLen+closeLen > len(s) {
		return s
	}
	if r.passthroughInlineLabel == "" && r.passthroughBlockLabel == "" {
		return s
	}
	return s[openLen : len(s)-closeLen]
}

func (r *htmlRenderer) writePassthroughRaw(ctx *render.Context, s string) (ast.WalkStatus, error) {
	if r.passthroughInlineLabel != "" || r.passthroughBlockLabel != "" {
		ctx.WriteString(s)
	}
	return ast.WalkContinue, nil
}

func (r *htmlRenderer) newPassthroughHookContext(ctx *render.Context, ordinal int, inner, typ string, node ast.Node) *passthroughContext {
	if r.passthroughInlineLabel == "" {
		r.passthroughInlineLabel = "inline"
	}
	return &passthroughContext{
		ordinal:          ordinal,
		page:             ctx.DocumentContext().Document,
		pageInner:        r.getPageInner(ctx),
		inner:            inner,
		typ:              typ,
		AttributesHolder: attributes.New(node.Attributes(), attributes.AttributesOwnerGeneral),
	}
}

type passthroughContext struct {
	page      any
	pageInner any
	typ       string
	inner     string
	ordinal   int
	pos       htext.Position
	posInit   sync.Once
	createPos func() htext.Position
	*attributes.AttributesHolder
}

func (p *passthroughContext) Page() any { return p.page }

func (p *passthroughContext) PageInner() any { return p.pageInner }

